CREATE TABLE "better_supabase"."guest_grants" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"    uuid                     NOT NULL,
  "guest_id"     uuid                     NOT NULL,
  "subject_type" text                     NOT NULL,
  "subject_id"   text                     NOT NULL,
  "actions"      text[]                   NOT NULL,
  "granted_by"   uuid,
  "expires_at"   timestamp with time zone,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "guest_grants_actions_check"
    CHECK (((cardinality(actions) > 0) AND (actions <@ ARRAY['read'::text, 'comment'::text, 'upload'::text]) AND ('read'::text = ANY (actions)))),
  CONSTRAINT "guest_grants_guest_id_subject_type_subject_id_key" UNIQUE (guest_id, subject_type, subject_id),
  CONSTRAINT "guest_grants_pkey" PRIMARY KEY (id),
  CONSTRAINT "guest_grants_subject_id_check" CHECK (((length(subject_id) >= 1) AND (length(subject_id) <= 200))),
  CONSTRAINT "guest_grants_subject_type_check" CHECK ((subject_type ~ '^[a-z][a-z0-9_-]{0,62}$'::text))
);

ALTER TABLE "better_supabase"."guest_grants"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."guests" (
  "id"          uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"   uuid                     NOT NULL,
  "email"       text                     NOT NULL,
  "name"        text,
  "user_id"     uuid,
  "party_type"  text,
  "party_id"    text,
  "status"      text                     NOT NULL DEFAULT 'invited'::text,
  "token_hash"  text,
  "invited_by"  uuid,
  "expires_at"  timestamp with time zone,
  "accepted_at" timestamp with time zone,
  "revoked_at"  timestamp with time zone,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "guests_check1" CHECK (((status <> 'active'::text) OR (user_id IS NOT NULL))),
  CONSTRAINT "guests_check" CHECK (((party_type IS NULL) = (party_id IS NULL))),
  CONSTRAINT "guests_email_check" CHECK (((length(email) >= 3) AND (length(email) <= 320) AND (POSITION(('@'::text) IN (email)) > 1))),
  CONSTRAINT "guests_name_check" CHECK (((name IS NULL) OR ((length(name) >= 1) AND (length(name) <= 200)))),
  CONSTRAINT "guests_pkey" PRIMARY KEY (id),
  CONSTRAINT "guests_status_check" CHECK ((status = ANY (ARRAY['invited'::text, 'active'::text, 'revoked'::text]))),
  CONSTRAINT "guests_token_hash_key" UNIQUE (token_hash)
);

ALTER TABLE "better_supabase"."guests"
