CREATE OR REPLACE FUNCTION better_supabase.accept_guest_invite (
  token text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."guests"%rowtype;
  v_email text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if auth.uid() is null then
    raise exception 'sign in to accept the invite' using errcode = '42501', hint = 'GUEST_SIGN_IN_REQUIRED';
  end if;
  select * into v_row from "better_supabase"."guests" x
    where x."token_hash" = encode(extensions.digest(convert_to(accept_guest_invite.token, 'utf8'), 'sha256'), 'hex')
      and x."status" = 'invited'
      and (x."expires_at" is null or x."expires_at" > now())
    for update;
  if not found then
    raise exception 'this invite is not valid or has expired' using errcode = 'P0002', hint = 'GUEST_INVITE_INVALID';
  end if;
  select lower(u.email) into v_email from auth.users u
    where u.id = auth.uid() and u.email_confirmed_at is not null;
  if v_email is distinct from lower(v_row."email") then
    raise exception 'this invite was sent to another email' using errcode = '42501', hint = 'GUEST_EMAIL_MISMATCH';
  end if;
  if exists (
    select 1 from "better_supabase"."guests" x
    where x."tenant_id" = v_row."tenant_id" and x."user_id" = auth.uid() and x."id" <> v_row."id"
  ) then
    raise exception 'you are already a guest of this organization' using errcode = '23505', hint = 'GUEST_ALREADY_GUEST';
  end if;
  update "better_supabase"."guests" x set
    "user_id" = auth.uid(),
    "status" = 'active',
    "token_hash" = null,
    "accepted_at" = now(),
    "updated_at" = now()
    where x."id" = v_row."id"
    returning * into v_row;
  perform "better_supabase".emit_event('guest.accepted', jsonb_build_object('organizationId', v_row."tenant_id"::text, 'id', v_row."id", 'userId', v_row."user_id"), 'guests/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/guests');
  perform better_supabase.audit_event(
    event_type => 'guest.accepted',
    category => 'access',
    target_type => 'guest',
    record_id => v_row."id"::text,
    target_label => v_row."email",
    summary => 'guest accepted ' || v_row."email",
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id"::text, 'id', v_row."id", 'userId', v_row."user_id")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id"::text, 'email', v_row."email", 'name', v_row."name", 'userId', v_row."user_id", 'partyType', v_row."party_type", 'partyId', v_row."party_id", 'status', v_row."status", 'invitedBy', v_row."invited_by", 'expiresAt', v_row."expires_at", 'acceptedAt', v_row."accepted_at", 'revokedAt', v_row."revoked_at", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.attachment_authors (
  ids uuid[]
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_object_agg(y."id"::text, jsonb_build_object('id', pr."id", 'name', coalesce(nullif(pr."full_name", ''), nullif(trim(concat_ws(' ', pr."first_name", pr."last_name")), ''), pr."username"), 'avatarUrl', pr."avatar_url")), '{}'::jsonb)
  from "better_supabase"."attachments" y
  join "better_supabase"."profiles" pr on pr."id" = y."uploaded_by"
  where y."id" = any ($1)
    and (y."organization_id" in (select better_supabase.tenant_ids_with('attachments.read')) or ((y."organization_id")::text, (y."subject_type")::text, (y."subject_id")::text) in (select g.tenant, g.subject_type, g.subject_id from better_supabase.portal_subjects('read') g))
$function$;

CREATE OR REPLACE FUNCTION better_supabase.attachment_object_allowed (
  bucket text,
  path   text,
  action text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from "better_supabase"."attachments" a
    where a."bucket" = attachment_object_allowed.bucket and a."object_path" = attachment_object_allowed.path
      and case attachment_object_allowed.action
        when 'insert' then a."status" = 'pending' and a."uploaded_at" is null and a."uploaded_by" = auth.uid()
        when 'select' then (a."status" in ('pending', 'clean', 'failed') and (coalesce(better_supabase.can('tenant', a."organization_id", 'attachments.read'), false) or ((a."organization_id")::text, (a."subject_type")::text, (a."subject_id")::text) in (select g.tenant, g.subject_type, g.subject_id from better_supabase.portal_subjects('read') g)))
          or a."uploaded_by" = auth.uid() or coalesce(better_supabase.can('tenant', a."organization_id", 'attachments.manage'), false)
        when 'delete' then a."uploaded_by" = auth.uid() or coalesce(better_supabase.can('tenant', a."organization_id", 'attachments.manage'), false)
        else false
      end
  )
$function$;

